import { defineConfig } from 'orval'

// Same header as orval's built-in one, without the emoji.
const header = (info: { title: string; version: string }) => [
  'Generated by orval. Do not edit manually.',
  info.title,
  `OpenAPI spec version: ${info.version}`,
]

export default defineConfig({
  api: {
    input: '../api/openapi.yaml',
    output: {
      mode: 'single',
      target: 'src/api/gen/api.ts',
      client: 'react-query',
      httpClient: 'fetch',
      override: {
        header,
        mutator: { path: 'src/api/fetcher.ts', name: 'apiFetch' },
        // Hooks return the response body itself, not { data, status, headers }.
        fetch: { includeHttpResponseReturnType: false },
      },
    },
  },
  apiZod: {
    input: '../api/openapi.yaml',
    output: {
      mode: 'single',
      target: 'src/api/gen/api.zod.ts',
      client: 'zod',
      override: { header },
    },
  },
})
